static TResult InTransaction<TResult>(Db db, Func<TResult> body)
{
    using var tx = db.BeginTransaction();      // setup (itself disposable)
    try
    {
        var result = body();                   // body as an argument
        tx.Commit();                           // teardown: success path
        return result;
    }
    catch { tx.Rollback(); throw; }            // teardown: failure path
}

